import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { connectPhi } from '../phi-ai/phi-agent-dsh/plugins/phi-cdp/src/lib/connection.ts';
import { resolveUserSpaceId } from '../phi-ai/phi-agent-dsh/plugins/phi-cdp/src/lib/tabs.ts';
import { normalizeBrowserTaskTabGroupTitle } from '../phi-ai/shared-types/tab-group-title.ts';

const credentials = JSON.parse(readFileSync(0, 'utf8'));
const request = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const prefix = process.argv[3];
const work = process.env.LANE_WORKDIR!;
const directory = join(work, 'results', prefix);
mkdirSync(directory, { recursive: true, mode: 0o700 });
const save = (name: string, value: unknown) => writeFileSync(join(directory, name + '.json'), JSON.stringify(value));
const pause = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));
const runner = '/Applications/Phi Canary.app/Contents/Library/LoginItems/Phi Sentinel.app/Contents/MacOS/runnerctl';
const { auth_token } = JSON.parse(execFileSync(runner, ['--channel', 'canary', '--compact', 'get-auth-token'], { encoding: 'utf8' }));
const seenPath = join(work, 'seen-sessions.json');
let seen: string[] = [];
try { seen = JSON.parse(readFileSync(seenPath, 'utf8')); } catch {}
if (seen.includes(request.sessionId)) throw new Error('Refusing reused session ID');
seen.push(request.sessionId); writeFileSync(seenPath, JSON.stringify(seen));
const c = await connectPhi({ channel: 'canary', verifyTimeoutMs: 15000 });
const spaceId = await resolveUserSpaceId(c);
const observations: any[] = [];
let baselineTokens = new Set<string>();
let baselineTabIds = new Set<number>();
const newTabIds = new Set<number>();
let stopped = false;
let lastSignature = '';
let totalSamples = 0;
async function observe(baseline = false) {
  const begin = Date.now();
  try {
    const groups = await c.requestPrivate('agentSpace.tabGroups.list', { spaceId }, { timeoutMs: 2000 });
    const tabs = await c.requestPrivate('agentSpace.spaces.listTabs', { spaceId }, { timeoutMs: 2000 });
    const allGroups = groups.groups as any[];
    const allTabs = (tabs.tabs ?? []) as any[];
    if (groups.ok === false || tabs.ok === false || !Array.isArray(allGroups)) throw new Error('Invalid group/tab response');
    if (baseline) {
      baselineTokens = new Set(allGroups.map(g => g.token));
      baselineTabIds = new Set(allTabs.map(t => t.tabId));
    }
    const relevantGroups = allGroups.filter(g => !baselineTokens.has(g.token));
    for (const group of relevantGroups) for (const id of group.tabIds ?? []) newTabIds.add(id);
    const relevantTabs = allTabs.filter(t => newTabIds.has(t.tabId) && !baselineTabIds.has(t.tabId))
      .map(({ tabId, url, title, targetId }: any) => ({ tabId, url, title, targetId }));
    const state = { spaceId, groups: relevantGroups, tabs: relevantTabs };
    const signature = JSON.stringify(state);
    totalSamples++;
    if (!baseline && signature === lastSignature && observations.length) {
      const last = observations[observations.length-1]; last.lastReadStartedAt = begin; last.lastReadFinishedAt = Date.now(); last.count++;
    } else {
      observations.push({ startedAt: begin, finishedAt: Date.now(), lastReadStartedAt: begin, lastReadFinishedAt: Date.now(), count: 1, baseline, ok: true, ...state });
      lastSignature = signature;
    }
  } catch (error) { lastSignature='';observations.push({ startedAt: begin, finishedAt: Date.now(), ok: false, error: String(error) }); }
}
await observe(true);
if (!observations[0]?.ok) { c.close(); throw new Error('Observer baseline failed'); }
save('observer-ready', { at: Date.now(), spaceId, originalTokens: [...baselineTokens], originalTabIds: [...baselineTabIds] });
const observing = (async () => { while (!stopped) { await observe(); if (!stopped) await pause(250); } })();
const startedAt = Date.now();
let response: any;
let statusCode: number | null = null;
try {
  const res = await fetch('http://127.0.0.1:' + process.env.LANE_AGENT_PORT + '/api/v1/browser-evals/run', {
    method: 'POST', headers: { authorization: 'Bearer ' + auth_token, 'content-type': 'application/json' },
    body: JSON.stringify(request), signal: AbortSignal.timeout(960000),
  });
  statusCode = res.status; response = await res.json();
} catch (error) { response = { status: 'error', error: String(error) }; }
const finishedAt = Date.now();
save('http', { startedAt, finishedAt, durationMs: finishedAt-startedAt, statusCode, request, response });
console.log(JSON.stringify({ prefix, phase:'http-complete', statusCode, status:response.status, durationMs:finishedAt-startedAt, steps:response.trajectory?.length, error:response.error }));
let trace: any = null;
let titleCalls: any[] = [];
let traceError: string | null = null;
async function lf(path: string) {
  const res = await fetch(credentials.LANGFUSE_HOST + '/api/public/' + path, {
    headers: { authorization: 'Basic ' + Buffer.from(credentials.LANGFUSE_PUBLIC_KEY + ':' + credentials.LANGFUSE_SECRET_KEY).toString('base64'), 'user-agent': 'PHI-475-experiment/1' },
    signal: AbortSignal.timeout(Math.max(1, Math.min(10000, terminalDeadline-Date.now()))),
  });
  if (!res.ok) throw new Error('Langfuse HTTP ' + res.status);
  return res.json();
}
const terminalDeadline = finishedAt + 60000;
while (Date.now() < terminalDeadline) {
  try {
    const query = new URLSearchParams({ name:'phi-agent.browser-eval', fields:'core,io', fromTimestamp:new Date(startedAt-1000).toISOString(), toTimestamp:new Date(finishedAt+1000).toISOString(), limit:'100' });
    const list = await lf('traces?' + query);
    for (const candidate of list.data ?? []) {
      if (candidate.input?.objective !== request.objective) continue;
      const detail = await lf('traces/' + candidate.id);
      const run = detail.observations?.find((o:any) => o.name === 'browser_use_sonic.run' && (o.metadata?.runId === request.sessionId || o.input?.request?.runId === request.sessionId));
      if (run) { trace=detail; break; }
    }
    titleCalls = trace?.observations?.filter((o:any) => o.type==='GENERATION' && o.input?.payload?.tools?.some((t:any)=>t.name==='set_tab_group_title')) ?? [];
    const runTerminal = trace?.observations?.some((o:any)=>o.name==='browser_use_sonic.run'&&o.endTime);
    const generationsTerminal = trace?.observations?.filter((o:any)=>o.type==='GENERATION').every((o:any)=>o.endTime);
    if (titleCalls.length && titleCalls.every((o:any)=>o.endTime) && runTerminal && generationsTerminal) break;
  } catch (error) { traceError=String(error); }
  await pause(Math.min(3000, Math.max(0, terminalDeadline-Date.now())));
}
stopped = true; await observing; await observe(); c.close();
save('observer', { spaceId, intervalMs:250, readTimeoutMs:2000, totalSamples, observations });
if (trace) save('trace', trace);
const groups = new Map<string, any[]>();
for (const observation of observations) for (const group of observation.groups ?? []) {
  const list = groups.get(group.token) ?? [];list.push({ ...group, tabs:observation.tabs, at:observation.finishedAt });groups.set(group.token,list);
}
const urls = new Set<string>((response.trajectory ?? []).map((step:any)=>step.url).filter(Boolean));
const qualified = [...groups.entries()].filter(([,states])=>states.some(s=>s.tabs.some((t:any)=>s.tabIds.includes(t.tabId)&&urls.has(t.url))));
const groupUnambiguous = qualified.length===1;
const expectedTitles = titleCalls.flatMap((o:any) => {
  const direct=o.output?.toolCall?.arguments?.title;
  if (typeof direct==='string') return [normalizeBrowserTaskTabGroupTitle(direct)];
  return (o.output?.output??[]).flatMap((item:any)=>{try{return item.name==='set_tab_group_title'?[normalizeBrowserTaskTabGroupTitle(JSON.parse(item.arguments).title)]:[];}catch{return [];}});
});
const applied = groupUnambiguous && qualified[0][1].some(s=>s.at<=finishedAt && expectedTitles.includes(s.title));
const run = trace?.observations?.find((o:any)=>o.name==='browser_use_sonic.run');
const summary = { prefix, sessionId:request.sessionId, startedAt, finishedAt, durationMs:finishedAt-startedAt, statusCode,
  status:response.status, error:response.error??null, traceId:trace?.id??null,
  freshRunVerified:response.sessionId===request.sessionId && Boolean(run?.input?.request?.runId===request.sessionId) && Date.parse(run.startTime)>=startedAt,
  title:{calls:titleCalls.length, allTerminal:titleCalls.length>0&&titleCalls.every((o:any)=>o.endTime), expectedTitles,
    groupUnambiguous, groupToken:groupUnambiguous?qualified[0][0]:null, applicationVerified:applied,
    cleanupObserved:observations.some(o=>o.ok&&!o.baseline&&o.lastReadStartedAt>=finishedAt&&o.groups.length===0),
    traceError, terminalWaitMs:Date.now()-finishedAt, truncated:!titleCalls.length||titleCalls.some((o:any)=>!o.endTime)},
  steps:response.trajectory?.length??0, screenshots:response.trajectory?.filter((s:any)=>s.screenshot?.base64).length??0,
  observerErrors:observations.filter(o=>!o.ok).length };
save('summary',summary); console.log(JSON.stringify(summary));
process.exit(0);

