import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { connectPhi } from '../phi-ai/phi-agent-dsh/plugins/phi-cdp/src/lib/connection.ts';
const c=await connectPhi({channel:'canary',verifyTimeoutMs:15000});
const work=process.env.LANE_WORKDIR!;
const out=join(work,'recordings');mkdirSync(out,{recursive:true});
const base='http://127.0.0.1:'+process.env.LANE_SITE_PORT_RANGE!.split('-')[0]+'/';
const pause=(ms:number)=>new Promise(r=>setTimeout(r,ms));
const ownTargets:string[]=[];
let panelSession:string|undefined;
let callerTargetId:string|undefined;
async function evaluate(session:string,expression:string) {
 const [sessionId,context]=session.split('@');
 const r=await c.request('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true,...(context?{contextId:Number(context)}:{})},{cdpSessionId:sessionId,timeoutMs:15000});
 if(r.exceptionDetails)throw new Error(JSON.stringify(r.exceptionDetails));return r.result?.value;
}
async function attached(targetId:string){return (await c.request('Target.attachToTarget',{targetId,flatten:true})).sessionId as string;}
async function click(session:string,selector:string){
 const p=await evaluate(session,`(()=>{const el=document.querySelector(${JSON.stringify(selector)});if(!el)throw new Error('Missing control');el.scrollIntoView({block:'center'});const b=el.getBoundingClientRect();return {x:b.x+b.width/2,y:b.y+b.height/2}})()`);
 await c.request('Input.dispatchMouseEvent',{type:'mousePressed',button:'left',clickCount:1,...p},{cdpSessionId:session});
 await c.request('Input.dispatchMouseEvent',{type:'mouseReleased',button:'left',clickCount:1,...p},{cdpSessionId:session});await pause(350);
}
async function key(session:string,key:string,code:string,virtual:number,modifiers=0){
 await c.request('Input.dispatchKeyEvent',{type:'keyDown',key,code,windowsVirtualKeyCode:virtual,modifiers},{cdpSessionId:session});
 await c.request('Input.dispatchKeyEvent',{type:'keyUp',key,code,windowsVirtualKeyCode:virtual,modifiers},{cdpSessionId:session});await pause(180);
}
async function input(session:string,selector:string,value:string){await click(session,selector);await evaluate(session,`(()=>{const el=document.querySelector(${JSON.stringify(selector)});el.focus();el.select();return true})()`);await c.request('Input.insertText',{text:value},{cdpSessionId:session});await pause(350);}
async function selectNext(session:string,selector:string){await evaluate(session,`(()=>{const el=document.querySelector(${JSON.stringify(selector)});el.selectedIndex=1;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));return el.value})()`);await pause(350);}
async function panelFor(topSession:string){
 const contexts:any[]=[];const off=c.on('Runtime.executionContextCreated',(p:any)=>contexts.push(p.context),topSession);
 await c.request('Runtime.enable',{}, {cdpSessionId:topSession});
 for(let i=0;i<30;i++){
  const tree=await c.request('Page.getFrameTree',{}, {cdpSessionId:topSession});
  const frames:any[]=[];const walk=(x:any)=>{if(x?.frame)frames.push(x.frame);for(const a of x?.childFrames??[])walk(a);};walk(tree.frameTree);
  const targetFrames=(await c.request('Target.getTargets')).targetInfos as any[];
  const detachedFrame=targetFrames.find(t=>t.type==='iframe'&&t.parentId===tree.frameTree?.frame?.id&&t.url?.includes('pjlnhbfabokjejbhmgghmjiaknfhnima/recorder-panel.html'));
  const frame=frames.find(f=>f.url?.includes('pjlnhbfabokjejbhmgghmjiaknfhnima/recorder-panel.html'))??(detachedFrame?{id:detachedFrame.targetId}:undefined);
  if(frame){
   try{const context=contexts.find(x=>x.auxData?.frameId===frame.id&&x.auxData?.isDefault);const sid=detachedFrame?await attached(frame.id):context?topSession+'@'+context.id:await attached(frame.id);await evaluate(sid,`window.__phi475={messages:[]};window.addEventListener('message',e=>{if(e.data?.source==='phi-recorder-content')window.__phi475.messages.push(e.data)});true`);off();return sid;}catch(error){if(i===3)console.log('panel attach:',String(error));}
  }
  if(i===29)writeFileSync(join(out,'record-debug.json'),JSON.stringify({frames,contexts,targets:await c.request('Target.getTargets')},null,2));
  await pause(250);
 }
 off();throw new Error('Recorder panel did not become available');
}
async function screenshot(session:string,name:string){const r=await c.request('Page.captureScreenshot',{format:'png'},{cdpSessionId:session});writeFileSync(join(out,name+'.png'),Buffer.from(r.data as string,'base64'));}
try{
 const targets=(await c.request('Target.getTargets')).targetInfos as any[];
 const sidecar=targets.find(t=>t.type==='service_worker'&&t.url.includes('fenmfiepnpdlhplemgijlimpbebebljo'));
 if(!sidecar){callerTargetId=(await c.request('Target.createTarget',{url:'chrome-extension://fenmfiepnpdlhplemgijlimpbebebljo/index.html'})).targetId as string;await pause(1200);}
 const sidecarSession=await attached(sidecar?.targetId??callerTargetId!);
 for(const name of (process.argv[2]?[process.argv[2]]:['R-L','R-M','R-H'])){
  const startedAt=Date.now();const url=base+'?sample='+name;
  const {targetId}=await c.request('Target.createTarget',{url});ownTargets.push(targetId as string);
  await c.request('Target.activateTarget',{targetId});const session=await attached(targetId as string);await pause(700);
  const tabId=await evaluate(sidecarSession,`(async()=>{const tabs=await chrome.tabs.query({});const tab=tabs.find(t=>t.url===${JSON.stringify(url)});if(!tab)throw new Error('No fixture tab');return tab.id})()`);
  const started=await evaluate(sidecarSession,`chrome.runtime.sendMessage('pjlnhbfabokjejbhmgghmjiaknfhnima',{action:'phiRecorderStartInTab',tabId:${tabId}})`);
  if(!started?.ok)throw new Error('Recorder start rejected: '+JSON.stringify(started));
  panelSession=await panelFor(session);await pause(300);
  await input(session,'#query',name==='R-M'?'blue notebook':'blue');
  if(name==='R-M')await selectNext(session,'#category');
  await click(session,'#search button');
  if(name!=='R-L')await selectNext(session,'#sort');
  let activeSession=session;
  if(name==='R-H'){
   await screenshot(session,name+'-search');await click(session,'article[data-product="mug"] a');
   let detail:any;
   for(let i=0;i<30;i++){detail=((await c.request('Target.getTargets')).targetInfos as any[]).find(t=>t.type==='page'&&t.url===base+'?product=mug');if(detail)break;await pause(200);}
   if(!detail)throw new Error('Detail tab did not open');ownTargets.push(detail.targetId);await c.request('Target.activateTarget',{targetId:detail.targetId});
   activeSession=await attached(detail.targetId);await pause(700);panelSession=await panelFor(activeSession);
   await input(activeSession,'#quantity','2');await input(activeSession,'#note','PHI-475 sample');await click(activeSession,'#preview button');
  }
  const facts=await evaluate(activeSession,`({url:location.href,count:document.querySelector('#count')?.textContent,status:document.querySelector('#status')?.textContent,resultIds:[...document.querySelectorAll('article')].map(x=>x.dataset.product),query:document.querySelector('#query')?.value,category:document.querySelector('#category')?.value,sort:document.querySelector('#sort')?.value,quantity:document.querySelector('#quantity')?.value,note:document.querySelector('#note')?.value,valid:document.querySelector('#preview')?.checkValidity()})`);
  if(name==='R-L'&&facts.count!=='3 results')throw new Error('Short fixture outcome mismatch');
  if(name==='R-M'&&(facts.count!=='2 results'||facts.category!=='Stationery'||facts.sort!=='price'))throw new Error('Medium fixture outcome mismatch: '+JSON.stringify(facts));
  if(name==='R-H'&&facts.status!=='Saved preview: Blue Travel Mug; quantity=2; total=$36; note=PHI-475 sample')throw new Error('Heavy fixture outcome mismatch: '+JSON.stringify(facts));
  await screenshot(activeSession,name+'-final');
  await evaluate(panelSession,`window.parent.postMessage({source:'phi-recorder-panel',type:'stop'},'*');true`);
  let captured:any;
  for(let i=0;i<30;i++){captured=await evaluate(panelSession,`window.__phi475.messages.find(x=>x.type==='recording-complete')`);if(captured)break;await pause(200);}
  if(!captured?.actions?.length)throw new Error('No real recorded actions');
  const tabs=[...new Set(captured.actions.map((a:any)=>a.tabIndex))];
  if(name==='R-H'&&tabs.length<2)throw new Error('Cross-tab recording was not captured');
  writeFileSync(join(out,name+'.json'),JSON.stringify({sample:name,startedAt,finishedAt:Date.now(),captureSource:'installed Kensington recorder; CDP Input events and HTML select input/change events; recording-complete message',facts,request:{actions:captured.actions,url:facts.url},rawEventCount:captured.events?.length,tabIndices:tabs},null,2));
  console.log(JSON.stringify({sample:name,actions:captured.actions.length,tabs,facts}));
  await evaluate(panelSession,`window.parent.postMessage({source:'phi-recorder-panel',type:'close'},'*');true`);panelSession=undefined;
  for(const id of ownTargets.splice(0))await c.request('Target.closeTarget',{targetId:id}).catch(()=>{});
