import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { evalSteps } from '../phi-ai/browser-use-eval/src/adapters/agents/phi-browser.ts';
import { judgeOnlineMind2WebTask } from '../phi-ai/browser-use-eval/src/adapters/benchmarks/online-mind2web-official.ts';
const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const runner = '/Applications/Phi Canary.app/Contents/Library/LoginItems/Phi Sentinel.app/Contents/MacOS/runnerctl';
const { auth_token } = JSON.parse(execFileSync(runner, ['--channel', 'canary', '--compact', 'get-auth-token'], { encoding: 'utf8' }));
const response = input.response;
const taskId = input.request.sessionId.split(':')[1];
const dataset = JSON.parse(readFileSync(new URL('../phi-ai/browser-use-eval/datasets/online-mind2web/Online_Mind2Web.json', import.meta.url), 'utf8'));
const original = dataset.find((t:any)=>t.task_id===taskId);
const task = { id: original?.task_id ?? input.request.sessionId, benchmark: 'online-mind2web', objective: original?.confirmed_task ?? input.request.objective };
const timeScale = input.startedAt < 100000000000 ? 1000 : 1;
const result = { taskId: task.id, status: response.status === 'ok' ? 'completed' : 'failed',
  finalAnswer: typeof response.result === 'string' ? response.result : JSON.stringify(response.result),
  startedAt: input.startedAt * timeScale, finishedAt: input.finishedAt * timeScale,
  durationMs: (input.finishedAt - input.startedAt) * timeScale, steps: evalSteps(response.trajectory) };
const startedAt = Date.now();
try {
  const verdict = await judgeOnlineMind2WebTask(task as any, result as any, {
    baseUrl: 'https://ai-service.stag.phibrowser.com/v1', apiKey: auth_token,
    model: 'openai/gpt-4.1-mini', userAgent: 'PHI-475-WebJudge',
  });
  const output = { startedAt, finishedAt: Date.now(), model: 'openai/gpt-4.1-mini', verdict };
  writeFileSync(process.argv[3], JSON.stringify(output, null, 2));
  console.log(JSON.stringify({taskId:task.id,score:(verdict as any).score,durationMs:output.finishedAt-startedAt}));
} catch (error) {
  const output = { startedAt, finishedAt: Date.now(), judgeStatus: 'judge_error', error: String(error) };
  writeFileSync(process.argv[3], JSON.stringify(output, null, 2));
  console.log(JSON.stringify(output));
  process.exitCode = 1;
}
